P BY 1,2,3,5 UNION ALL SELECT vouch_date AS inwarded_date, bill_date, bill_no, SUM(quantity) AS sti_qty, to_party AS receiving_PV FROM snitch_db.maplemonk.logic_purchase_voucher WHERE from_party IN ( \'SNITCH - WH - GUJARAT -SURAT\', \'SNITCH - WH - U.P -LUCKNOW\', \'SNITCH - WH - RAJASTHAN -JAIPUR\', \'SNITCH - WH - MADHYA PRADESH -INDORE\' ) AND bill_date >= \'2025-02-01\' GROUP BY 1,2,3,5 UNION ALL SELECT * FROM snitch_db.maplemonk.sti_manual ) SELECT u.*, sto.*, eship.*, sti.*, CASE WHEN tracking_status = \'Exception\' AND tracking_pick_date::DATE = \'2025-01-17\' THEN \'MISSING_SHIPMENT_LOST\' WHEN LOWER(tracking_sub_status) LIKE ANY (\'%lost%\', \'%damage%\', \'%short%\') THEN \'EXCEPTION_LOST_DAMAGE\' WHEN sti_qty IS NOT NULL THEN \'INWARDED\' WHEN logistics_delivery_timestamp IS NOT NULL THEN \'INWARD_PENDING\' WHEN tracking_pick_date IS NOT NULL THEN \'DELIVERY_PENDING\' WHEN logistics_created_timestamp IS NOT NULL THEN \'PICKUP_PENDING\' WHEN to_party IS NOT NULL THEN \'ESHIP_PENDING\' WHEN to_party IS NULL THEN \'WH_PENDING\' ELSE NULL END AS FINAL_STATUS, qty - sti_qty AS ex_short FROM uc u LEFT JOIN awb_find awb ON u.order_name = UPPER(TRIM(awb.find1)) LEFT JOIN sto ON CONCAT(UPPER(TRIM(u.order_name))) = CONCAT(UPPER(TRIM(sto.order_no))) LEFT JOIN eship ON UPPER(TRIM(awb.find2)) = UPPER(TRIM(eship.unique_order_id)) LEFT JOIN sti ON CONCAT(UPPER(TRIM(sto.sto_bill_no))) = CONCAT(UPPER(TRIM(sti.bill_no))) WHERE final_store LIKE ANY (\'%FOCO%\', \'%FOFO%\'); CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.checker_store_status AS WITH data AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.checker_own_store_status UNION ALL SELECT * FROM SNITCH_DB.MAPLEMONK.checker_journey_store_status ), new AS ( SELECT order_name AS identity1, type FROM snitch_db.maplemonk.gs_b2b_uc ), draft1 AS ( SELECT n.type, d.* FROM data d LEFT JOIN new n ON TRIM(d.order_name) = TRIM(n.identity1) ), final AS ( SELECT *, CASE WHEN final_status = \'WH_PENDING\' THEN TIMESTAMPDIFF(DAY, order_date, CURRENT_DATE) WHEN final_status = \'ESHIP_PENDING\' THEN TIMESTAMPDIFF(DAY, sto_bill_date, CURRENT_DATE) WHEN final_status = \'PICKUP_PENDING\' THEN TIMESTAMPDIFF(DAY, logistics_created_timestamp, CURRENT_DATE) WHEN final_status = \'DELIVERY_PENDING\' THEN TIMESTAMPDIFF(DAY, logistics_expected_delivery_date, CURRENT_DATE) WHEN final_status = \'INWARD_PENDING\' THEN TIMESTAMPDIFF(DAY, logistics_delivery_timestamp, CURRENT_DATE) ELSE NULL END AS STATUS_AGEING FROM draft1 ), numbered AS ( SELECT *, CASE final_status WHEN \'INWARDED\' THEN 1 WHEN \'INWARD_PENDING\' THEN 2 WHEN \'DELIVERY_PENDING\' THEN 3 WHEN \'PICKUP_PENDING\' THEN 4 WHEN \'ESHIP_PENDING\' THEN 5 WHEN \'WH_PENDING\' THEN 6 END AS status_priority, ROW_NUMBER() OVER ( PARTITION BY order_name ORDER BY CASE final_status WHEN \'INWARDED\' THEN 1 WHEN \'INWARD_PENDING\' THEN 2 WHEN \'DELIVERY_PENDING\' THEN 3 WHEN \'PICKUP_PENDING\' THEN 4 WHEN \'ESHIP_PENDING\' THEN 5 WHEN \'WH_PENDING\' THEN 6 END, order_date DESC ) AS rn FROM final ) SELECT * FROM numbered WHERE rn = 1; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OWN_B2B_JOURNEY AS WITH data AS ( SELECT marketplace, marketplace_mapped, order_name, CASE WHEN UPPER(SKU) LIKE ANY (\'%T-SHIRT%\', \'%CO-ORDS%\') THEN REGEXP_REPLACE(SKU, \'^([^-]+-[^-]+)-[^-]+-[^-]+-\', \'\1-\') WHEN REGEXP_COUNT(SKU, \'-\') = 3 THEN REGEXP_REPLACE(SKU, \'^([^-]+-[^-]+)-[^-]+-\', \'\1-\') ELSE SKU END AS SKU, COUNT(saleorderitemcode) AS qty, order_timestamp, order_date, warehouse_name, address_line_1, tat, category, ageing AS a1 FROM snitch_db.maplemonk.warehouse_sla_performance WHERE order_date >= \'2025-02-15\' AND item_status NOT IN (\'CANCELLED\') GROUP BY 1,2,3,4,6,7,8,9,10,11,12 ), store AS ( SELECT state, store_name_format, so_code FROM snitch_db.maplemonk.gs_store_details ), uc AS ( SELECT d.*, s.store_name_format AS final_store, s.state FROM data d LEFT JOIN store s ON LEFT(d.order_name, 6) = s.so_code ), sto AS ( SELECT REGEXP_SUBSTR(order_no, \'^[^-]+\') AS order_no, TRY_